DROP TABLE IF EXISTS `backtest_run`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `backtest_run` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_at` datetime NOT NULL COMMENT 'Nepal time',
  `kind` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'STANDARD = textbook rules with exits, CUSTOM = app rules with fixed holding period',
  `data_from` date NOT NULL,
  `data_to` date NOT NULL,
  `sessions` int NOT NULL,
  `horizon` int DEFAULT NULL COMMENT 'holding sessions (CUSTOM runs)',
  `market_filter` tinyint(1) NOT NULL DEFAULT '0',
  `price_adjusted` tinyint(1) NOT NULL DEFAULT '0',
  `t2_settlement` tinyint(1) NOT NULL DEFAULT '0',
  `cost_pct` decimal(5,2) NOT NULL,
  `market_return_pct` decimal(9,3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_backtest_run` (`kind`,`data_from`,`data_to`,`sessions`,`horizon`,`market_filter`,`price_adjusted`,`t2_settlement`),
  KEY `idx_backtest_run_to` (`data_to`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
