--
-- Table structure for table `daily_price`
--

DROP TABLE IF EXISTS `daily_price`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_price` (
  `trade_date` date NOT NULL,
  `symbol` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `open_price` decimal(12,2) DEFAULT NULL,
  `high_price` decimal(12,2) DEFAULT NULL,
  `low_price` decimal(12,2) DEFAULT NULL,
  `close_price` decimal(12,2) DEFAULT NULL,
  `ltp` decimal(12,2) DEFAULT NULL,
  `prev_close` decimal(12,2) DEFAULT NULL,
  `vwap` decimal(12,2) DEFAULT NULL,
  `volume` decimal(16,2) DEFAULT NULL COMMENT 'shares traded',
  `turnover` decimal(18,2) DEFAULT NULL COMMENT 'Rs',
  `trades` int DEFAULT NULL COMMENT 'number of transactions',
  `change_pct` decimal(8,2) DEFAULT NULL,
  PRIMARY KEY (`trade_date`,`symbol`),
  KEY `idx_daily_price_symbol_date` (`symbol`,`trade_date`),
  CONSTRAINT `fk_daily_price_day` FOREIGN KEY (`trade_date`) REFERENCES `trading_day` (`trade_date`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

