--
-- Table structure for table `trading_day`
--

DROP TABLE IF EXISTS `trading_day`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trading_day` (
  `trade_date` date NOT NULL,
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `crawled_at` datetime NOT NULL COMMENT 'Nepal time',
  `stock_count` smallint NOT NULL,
  `total_turnover` decimal(18,2) DEFAULT NULL COMMENT 'Rs',
  `total_volume` decimal(18,2) DEFAULT NULL COMMENT 'shares',
  `total_trades` int DEFAULT NULL,
  PRIMARY KEY (`trade_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

